#include <complex>
#include <cmath>
#include <stdexcept>

typedef std::complex<double> dcomp;

dcomp calculate_mode_function(int mf_type, double x) {
    if (mf_type < 0 || mf_type > 3) {
        throw std::invalid_argument("Invalid mode function type. Expected 0, 1, 2, or 3.");
    }
    switch (mf_type) {
        case 0:
            return dcomp(std::sin(x), 0.0);
        case 1:
            return dcomp(std::cos(x), 0.0);
        case 2:
            return dcomp(std::cos(x), std::sin(x));
        case 3:
            return dcomp(std::cos(x), -std::sin(x));
    }
}
